/**
 * Abihacart Assistant — Urgent Order Confirmation Popup
 * Customer-Facing Shopify Thank You / Order Status Page Embed
 * Automatically triggers after successful Shopify checkout
 */
(function () {
  'use strict';

  // Prevent duplicate initialization
  if (window.__ABIHACART_ORDER_POPUP_LOADED__) return;
  window.__ABIHACART_ORDER_POPUP_LOADED__ = true;

  // Base64 Robot Avatar — 100% reliable, zero network latency, exact visual reference
  const ROBOT_AVATAR_SRC = 'data:image/png;base64,';

  // Resolve Backend URL
  const scriptTag = document.currentScript;
  let backendUrl = '';
  if (scriptTag && scriptTag.src) {
    try {
      const u = new URL(scriptTag.src);
      backendUrl = `${u.protocol}//${u.host}`;
    } catch (e) {}
  }
  if (!backendUrl) {
    backendUrl = window.ABIHACART_CONFIG?.backendUrl || window.location.origin;
  }

  // Detect Order Information from Shopify environment
  function detectShopifyOrder() {
    let orderId = '';
    let orderNumber = '';
    let token = '';
    let email = '';
    let phone = '';

    // 1. Check window.Shopify checkout object
    if (window.Shopify && window.Shopify.checkout) {
      const co = window.Shopify.checkout;
      orderId = co.order_id || co.order_number || '';
      orderNumber = co.order_number ? `#${co.order_number}` : '';
      email = co.email || '';
      phone = co.phone || '';
      token = co.token || '';
    }

    // 2. Check URL search parameters
    const params = new URLSearchParams(window.location.search);
    if (!orderId) orderId = params.get('order_id') || params.get('orderId') || '';
    if (!orderNumber) orderNumber = params.get('order_number') || params.get('orderNumber') || (orderId ? `#${orderId}` : '');
    if (!token) token = params.get('token') || '';
    if (!email) email = params.get('email') || '';
    if (!phone) phone = params.get('phone') || '';

    // 3. Check data attributes in DOM if embedded
    const rootEl = document.getElementById('abihacart-order-confirmation-root');
    if (rootEl) {
      if (!orderId && rootEl.dataset.orderId) orderId = rootEl.dataset.orderId;
      if (!orderNumber && rootEl.dataset.orderNumber) orderNumber = rootEl.dataset.orderNumber;
      if (!token && rootEl.dataset.token) token = rootEl.dataset.token;
    }

    return { orderId, orderNumber, token, email, phone };
  }

  // Inject CSS Styles
  function injectStyles() {
    if (document.getElementById('abihacart-popup-styles')) return;
    const style = document.createElement('style');
    style.id = 'abihacart-popup-styles';
    style.textContent = `
      .abh-popup-overlay {
        position: fixed;
        inset: 0;
        z-index: 999999;
        background: rgba(0, 0, 0, 0.55);
        backdrop-filter: blur(5px);
        -webkit-backdrop-filter: blur(5px);
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 16px;
        box-sizing: border-box;
        opacity: 0;
        visibility: hidden;
        transition: opacity 0.25s ease, visibility 0.25s ease;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      }
      .abh-popup-overlay.active {
        opacity: 1;
        visibility: visible;
      }
      .abh-popup-card {
        background: #ffffff;
        border-radius: 24px;
        max-width: 470px;
        width: 100%;
        box-shadow: 0 20px 50px rgba(0, 0, 0, 0.22);
        border: 1px solid rgba(0, 0, 0, 0.06);
        transform: translateY(16px) scale(0.98);
        transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1);
        display: flex;
        flex-direction: column;
        position: relative;
        overflow: hidden;
        box-sizing: border-box;
      }
      .abh-popup-overlay.active .abh-popup-card {
        transform: translateY(0) scale(1);
      }
      .abh-popup-header {
        display: flex;
        align-items: center;
        justify-content: flex-start;
        padding: 24px 28px 14px 28px;
        background: #ffffff;
        position: relative;
      }
      .abh-header-left {
        display: flex;
        align-items: center;
        gap: 16px;
      }
      .abh-robot-avatar {
        width: 78px;
        height: 72px;
        object-fit: contain;
        flex-shrink: 0;
      }
      .abh-brand-title {
        font-size: 19px;
        font-weight: 700;
        color: #111827;
        letter-spacing: -0.01em;
        line-height: 1.2;
        margin: 0;
      }
      .abh-status-pill {
        background: #dcfce7;
        color: #15803d;
        border-radius: 9999px;
        font-size: 12.5px;
        font-weight: 600;
        padding: 3px 12px;
        letter-spacing: 0.01em;
        display: inline-flex;
        align-items: center;
        gap: 4px;
        margin-top: 6px;
      }
      .abh-close-btn {
        position: absolute;
        top: 20px;
        right: 22px;
        background: none;
        border: none;
        color: #374151;
        cursor: pointer;
        font-size: 20px;
        line-height: 1;
        padding: 6px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: color 0.15s, background 0.15s;
        z-index: 2;
      }
      .abh-close-btn:hover {
        color: #111827;
        background: #f3f4f6;
      }
      .abh-popup-body {
        padding: 10px 28px 26px 28px;
        text-align: center;
      }
      .abh-greeting {
        font-size: 16.5px;
        font-weight: 500;
        color: #1f2937;
        margin-bottom: 8px;
        line-height: 1.45;
      }
      .abh-placed-text {
        font-size: 16.5px;
        color: #1f2937;
        margin-bottom: 14px;
        line-height: 1.45;
      }
      .abh-order-ref {
        font-weight: 700;
        color: #111827;
      }
      .abh-prompt-text {
        font-size: 17.5px;
        font-weight: 700;
        color: #111827;
        margin: 14px 0 22px 0;
      }
      .abh-actions {
        display: flex;
        flex-direction: column;
        gap: 12px;
        margin-bottom: 18px;
      }
      .abh-btn-confirm {
        width: 100%;
        background: #16a34a;
        color: #ffffff;
        border: none;
        padding: 14px 20px;
        border-radius: 12px;
        font-size: 16px;
        font-weight: 700;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        transition: background 0.15s, transform 0.1s;
        box-shadow: 0 4px 14px rgba(22, 163, 74, 0.25);
      }
      .abh-btn-confirm:hover {
        background: #15803d;
      }
      .abh-btn-confirm:active {
        transform: scale(0.99);
      }
      .abh-btn-cancel {
        width: 100%;
        background: #ffffff;
        color: #ef4444;
        border: 1.5px solid #ef4444;
        padding: 13px 20px;
        border-radius: 12px;
        font-size: 16px;
        font-weight: 700;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        transition: background 0.15s, color 0.15s;
      }
      .abh-btn-cancel:hover {
        background: rgba(239, 68, 68, 0.05);
        color: #dc2626;
      }
      .abh-icon-check {
        width: 22px;
        height: 22px;
        border-radius: 50%;
        background: #ffffff;
        color: #16a34a;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: 13px;
        font-weight: 900;
      }
      .abh-icon-cancel {
        width: 22px;
        height: 22px;
        border-radius: 50%;
        background: #ef4444;
        color: #ffffff;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: 12px;
        font-weight: 900;
      }
      .abh-btn:disabled {
        opacity: 0.65;
        cursor: not-allowed;
      }
      .abh-security-msg {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
        font-size: 12.5px;
        color: #6b7280;
        margin-top: 6px;
      }
      .abh-spinner {
        display: inline-block;
        width: 16px;
        height: 16px;
        border: 2px solid rgba(255, 255, 255, 0.3);
        border-radius: 50%;
        border-top-color: #ffffff;
        animation: abh-spin 0.8s linear infinite;
      }
      @keyframes abh-spin {
        to { transform: rotate(360deg); }
      }
      @media (max-width: 480px) {
        .abh-popup-card {
          width: 95%;
          margin: 10px;
          border-radius: 20px;
        }
        .abh-popup-header {
          padding: 18px 20px 12px 20px;
        }
        .abh-popup-body {
          padding: 8px 20px 20px 20px;
        }
        .abh-robot-avatar {
          width: 68px;
          height: 62px;
        }
        .abh-brand-title {
          font-size: 17px;
        }
        .abh-greeting, .abh-placed-text {
          font-size: 15px;
        }
        .abh-prompt-text {
          font-size: 16px;
          margin: 10px 0 16px 0;
        }
        .abh-btn-confirm, .abh-btn-cancel {
          padding: 12px 16px;
          font-size: 15px;
        }
      }
    `;
    document.head.appendChild(style);
  }

  // Create Popup DOM
  function createPopupModal(orderData, actions) {
    injectStyles();

    const existingOverlay = document.getElementById('abihacart-order-popup-overlay');
    if (existingOverlay) existingOverlay.remove();

    const overlay = document.createElement('div');
    overlay.id = 'abihacart-order-popup-overlay';
    overlay.className = 'abh-popup-overlay';

    const orderNumber = orderData.orderNumber || (orderData.shopifyOrderId ? `#${orderData.shopifyOrderId}` : 'Order');

    overlay.innerHTML = `
      <div class="abh-popup-card" role="dialog" aria-modal="true" aria-labelledby="abh-popup-title">
        <button class="abh-close-btn" id="abh-close-btn" aria-label="Close popup">✕</button>
        <div class="abh-popup-header">
          <div class="abh-header-left">
            <img src="${ROBOT_AVATAR_SRC}" alt="Abihacart Assistant" class="abh-robot-avatar" />
            <div>
              <h2 class="abh-brand-title" id="abh-popup-title">Abihacart Assistant</h2>
              <div class="abh-status-pill">Order Received ✓</div>
            </div>
          </div>
        </div>

        <div class="abh-popup-body" id="abh-popup-body">
          <div class="abh-greeting">Assalam-o-Alaikum! Thank you for shopping with <strong>Abihacart</strong>.</div>
          <div class="abh-placed-text">Your order <span class="abh-order-ref">${orderNumber}</span> has been placed successfully.</div>
          <div class="abh-prompt-text">Would you like to confirm your order?</div>

          <div class="abh-actions">
            <button class="abh-btn-confirm" id="abh-confirm-btn">
              <span class="abh-icon-check">✓</span> Confirm My Order
            </button>
            <button class="abh-btn-cancel" id="abh-cancel-btn">
              <span class="abh-icon-cancel">✕</span> Cancel My Order
            </button>
          </div>

          <div class="abh-security-msg">
            <span>🛡️</span> Your response is secure and will be processed immediately.
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);

    // Event Listeners
    const closeBtn = overlay.querySelector('#abh-close-btn');
    const confirmBtn = overlay.querySelector('#abh-confirm-btn');
    const cancelBtn = overlay.querySelector('#abh-cancel-btn');
    const bodyContainer = overlay.querySelector('#abh-popup-body');

    // Close button dismisses popup without changing order status
    closeBtn.addEventListener('click', () => {
      overlay.classList.remove('active');
    });

    // Confirm button
    confirmBtn.addEventListener('click', async () => {
      confirmBtn.disabled = true;
      cancelBtn.disabled = true;
      confirmBtn.innerHTML = `<span class="abh-spinner"></span> Confirming...`;

      try {
        const result = await actions.onConfirm();
        if (result && result.status === 'success' || result && result.success) {
          bodyContainer.innerHTML = `
            <div style="padding: 24px 10px; text-align: center;">
              <div style="width: 56px; height: 56px; border-radius: 50%; background: rgba(16, 185, 129, 0.15); border: 2px solid #10b981; color: #10b981; font-size: 28px; display: inline-flex; align-items: center; justify-content: center; margin-bottom: 16px;">✓</div>
              <h3 style="font-size: 18px; color: #111; margin-bottom: 8px;">Order Confirmed!</h3>
              <p style="font-size: 14px; color: #4b5563; margin-bottom: 20px;">Thank you! Your order has been confirmed successfully.</p>
              <button class="abh-btn-confirm" id="abh-done-btn" style="width: auto; padding: 10px 24px; margin: 0 auto;">Done</button>
            </div>
          `;
          bodyContainer.querySelector('#abh-done-btn').addEventListener('click', () => {
            overlay.classList.remove('active');
          });
        } else {
          alert((result && result.message) || 'Confirmation failed. Please try again.');
          confirmBtn.disabled = false;
          cancelBtn.disabled = false;
          confirmBtn.innerHTML = `<span class="abh-icon-check">✓</span> Confirm My Order`;
        }
      } catch (err) {
        alert('Network error. Please try again.');
        confirmBtn.disabled = false;
        cancelBtn.disabled = false;
        confirmBtn.innerHTML = `<span class="abh-icon-check">✓</span> Confirm My Order`;
      }
    });

    // Cancel button with confirmation safeguard
    cancelBtn.addEventListener('click', () => {
      bodyContainer.innerHTML = `
        <div style="padding: 16px 4px; text-align: center;">
          <div style="width: 50px; height: 50px; border-radius: 50%; background: rgba(239, 68, 68, 0.12); color: #ef4444; font-size: 24px; display: inline-flex; align-items: center; justify-content: center; margin-bottom: 14px;">⚠️</div>
          <h3 style="font-size: 17px; color: #111; margin-bottom: 8px;">Cancel Order ${orderNumber}?</h3>
          <p style="font-size: 13.5px; color: #555; margin-bottom: 20px;">Are you sure you want to cancel this order? This action cannot be undone.</p>
          <div style="display: flex; gap: 10px;">
            <button class="abh-btn-cancel" id="abh-keep-order-btn" style="border-color: #d1d5db; color: #374151;">Keep Order</button>
            <button class="abh-btn-confirm" id="abh-confirm-cancel-btn" style="background: #ef4444;">Yes, Cancel</button>
          </div>
        </div>
      `;

      bodyContainer.querySelector('#abh-keep-order-btn').addEventListener('click', () => {
        // Restore popup view
        createPopupModal(orderData, actions);
        requestAnimationFrame(() => overlay.classList.add('active'));
      });

      bodyContainer.querySelector('#abh-confirm-cancel-btn').addEventListener('click', async () => {
        const confirmCancelBtn = bodyContainer.querySelector('#abh-confirm-cancel-btn');
        confirmCancelBtn.disabled = true;
        confirmCancelBtn.innerHTML = `<span class="abh-spinner"></span> Cancelling...`;

        try {
          const result = await actions.onCancel();
          bodyContainer.innerHTML = `
            <div style="padding: 24px 10px; text-align: center;">
              <div style="width: 56px; height: 56px; border-radius: 50%; background: rgba(239, 68, 68, 0.12); border: 2px solid #ef4444; color: #ef4444; font-size: 28px; display: inline-flex; align-items: center; justify-content: center; margin-bottom: 16px;">✕</div>
              <h3 style="font-size: 18px; color: #111; margin-bottom: 8px;">Order Cancelled</h3>
              <p style="font-size: 14px; color: #4b5563; margin-bottom: 20px;">${(result && result.message) || 'Your order cancellation has been submitted.'}</p>
              <button class="abh-btn-cancel" id="abh-done-cancel-btn" style="width: auto; padding: 10px 24px; margin: 0 auto; color: #141414; border-color: #d1d5db;">Close</button>
            </div>
          `;
          bodyContainer.querySelector('#abh-done-cancel-btn').addEventListener('click', () => {
            overlay.classList.remove('active');
          });
        } catch (err) {
          alert('Network error while processing cancellation. Please contact support.');
        }
      });
    });

    requestAnimationFrame(() => {
      overlay.classList.add('active');
    });

    return overlay;
  }

  // Main Initialize on Page Load
  async function init() {
    const orderInfo = detectShopifyOrder();
    if (!orderInfo.orderId && !orderInfo.token) {
      return; // No order on this page
    }

    try {
      const query = new URLSearchParams({
        orderId: orderInfo.orderId || '',
        orderNumber: orderInfo.orderNumber || '',
        token: orderInfo.token || '',
        email: orderInfo.email || '',
        phone: orderInfo.phone || '',
      });

      const res = await fetch(`${backendUrl}/api/orders/checkout-confirmation-status?${query.toString()}`, {
        headers: { Accept: 'application/json' },
      });

      if (!res.ok) return;

      const data = await res.json();
      if (!data.success || !data.record) return;

      const record = data.record;

      // If already confirmed or cancelled, do not prompt repeatedly unless specifically targeted
      if (record.status === 'confirmed' || record.status === 'cancelled') {
        return;
      }

      // Open the Abihacart Assistant popup immediately
      createPopupModal(record, {
        onConfirm: async () => {
          const confirmRes = await fetch(`${backendUrl}/api/orders/confirm-shopify-order`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
            body: JSON.stringify({
              token: record.confirmationToken || orderInfo.token,
              orderId: record.shopifyOrderId || orderInfo.orderId,
            }),
          });
          return await confirmRes.json();
        },
        onCancel: async () => {
          const cancelRes = await fetch(`${backendUrl}/api/orders/cancel-shopify-order`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
            body: JSON.stringify({
              token: record.confirmationToken || orderInfo.token,
              orderId: record.shopifyOrderId || orderInfo.orderId,
              reason: 'Customer requested cancellation via Thank You popup',
            }),
          });
          return await cancelRes.json();
        },
      });
    } catch (err) {
      console.warn('[Abihacart Order Confirmation Popup] Init skipped:', err.message);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // Expose API for manual invocation or test fixtures
  window.AbihacartOrderPopup = {
    open: (orderData, actions) => createPopupModal(orderData, actions),
    init,
  };
  window.AbihacartAssistantPopup = window.AbihacartOrderPopup;
  window.initOrderConfirmationPopup = init;
})();
